INSERT INTO `product` (`id`, `slug`, `name`, `category_id`, `subcategory_id`, `description`, `code`, `price`, `availability`, `brand`, `status`, `concentration`, `dosage_form`, `is_season`) VALUES
(1, 'benagro', 'Бенагро', 1, 2, 'Гербицид для защиты сельскохозяйственных культур от одно летних двудольных сорняков. Обладает выраженным контакт ным действием и поглощается преимущественно зелеными  частями растений.  Действующее вещество прерывает реакцию фотосинтеза.  Отмирание сорняков проявляется через 3-5 суток.', 0, 121, 0, '', 1, ' Бентазон – 480 г/л.', ' Водный раствор.', 1),
(2, 'madzhestik', 'Маджестик', 1, 2, ' Данный препарат эффективен против широкого спектра  трудно контролируемых сорняков, особенно таких как осот,  подмаренник цепкий и др., широкое окно внесения – от появления 2-х листков до флагового листа культуры. Низкая норма  внесения (10-20 г/га), что обеспечивает простоту и удобство  в использовании. Остановка роста сорняков через 2-3 часа,  гибель через 2-3 недели. Дождь, выпавший через 3 часа после обработки, не снижает эффективности препарата.  Селективен по отношению к пшенице, ячменю и ржи. Наибольшая эффективность – от стадии 3 листьев до первого  междоузлия культуры, что соответствует стадии развития сорняков от 3 до 6 листьев.', 0, 122, 0, '', 1, ' Трибенурон-метил 750 г/кг.', ' Водно-диспергируемые гранулы.', 0),
(3, 'geksilen-905', 'Гексилен 905', 1, 2, ' Гербицид системного и избирательного действия,  предназначенный для борьбы с широким спектром  однолетних и многолетних двудольных сорняков  в посевах зерновых культур.  Применение в посевах зерновых колосовых культур  наиболее эффективно в фазе кущения культуры  и при активном росте сорняков.', 0, 123, 0, '', 1, ' 2,4-Д кислоты в виде 2-этилгексилового эфира, 905 г/л.', ' Концентрат эмульсии.', 0),
(4, 'glifat-forte-757', ' Глифат Форте 757', 1, 2, ' Гербицид сплошного действия, предназначенный для борьбы  с широким спектром однолетних и многолетних злаковых и  двудольных сорняков на парах и полях, предназначенных  под посев зерновых и других с/х культур.  Благодаря системному действию уничтожает надземную  часть сорняков и их корневую систему.  Визуально действие препарата можно наблюдать через 4-7  дней на однолетних и 10-14 дней - на многолетних сорняках.  Прохладная погода может замедлить действие препарата.  Период защитного действия - 1 месяц и более, до появления  новой волны сорняков.', 0, 124, 0, '', 1, ' Глифосат 757 г/кг.', ' Водно-диспергируемые гранулы.', 0),
(5, 'glifosat-540', ' Глифосат 540\n', 1, 2, ' Гербицид сплошного действия, предназначенный для борьбы  с широким спектром однолетних и многолетних злаковых и  двудольных сорняков на парах и полях, предназначенных  под посев зерновых и других с/х культур.  Благодаря системному действию уничтожает надземную  часть сорняков и их корневую систему. Визуально действие  препарата можно наблюдать через 4-7 дней на однолетних  и 10-14 дней - на многолетних сорняках. Прохладная погода  может замедлить действие препарата. Период защитного действия - 1 месяц и более, до появления новой волны сорняков.', 0, 125, 0, '', 1, ' Глифосат калийная соль, 540 г/л.', ' Водный раствор.', 0),
(6, 'triofen', 'Триофен', 1, 2, 'Селективный гербицид для послевсходового контроля однолетних двудольных сорняков (включая виды щирицы) и  некоторых злаковых сорняков (куриное просо, щетинники,  метлица полевая) в посевах сахарной, столовой и кормовой  свёклы. Десмедифам и фенмедифам - проникают в сорные  растения через листовой аппарат и ингибируют процесс фотосинтеза в листьях сорного растения (ингибируют реакцию  Хилла). Этофумезат - поглощается как листьями, так и корневой системой сорного растения. Действие этофумезата выражается в сильном замедлении митоза.', 0, 126, 0, '', 1, ' Фенмедифам, 91 г/л + десмедифам, 71 г/л + этофумезат, 112 г/л.', ' Концентрат эмульсии.', 1),
(7, 'general', 'Генерал', 1, 2, ' Послевсходовый системный гербицид, предназначенный для  борьбы с однолетними и многолетними злаковыми сорняками  в посевах ряда сельскохозяйственных культур. Не действует  на двудольные сорняки.  Применяют в период активного роста сорняков. Важно, чтобы на них было достаточно листьев для быстрого поглощения  действующего вещества. Обработку желательно проводить в  сухую погоду. Не рекомендуется обрабатывать влажные растения. Однолетние злаковые сорняки опрыскивают в период их  активного роста (в фазе от 2-4 листьев до кущения), многолетние злаковые - при их высоте 10- 15 см. Сроки обработки  не зависят от стадии развития культуры, однако культурные  растения не должны закрывать собой сорняки, мешая их  равномерному опрыскиванию.', 0, 127, 0, '', 1, ' Галоксифоп-Р-метил, 108 г/л.', ' Концентрат эмульсии.', 0),
(8, 'oksifen-240', 'Оксифен 240', 1, 2, ' Довсходовый гербицид против однолетних двудольных сорняков на посевах подсолнечника, лука, сафлор и в садовых посадках. Данный препарат действует двумя разными путями. При  обработке посевов до прорастания сорняков Оксифен 240 к. э.  практически не перемещается в почве и не смывается водой,  образуя на поверхности почвы гербицидный экран, который  ингибирует развитие сорняков до тех пор, пока не нарушится  его целостность. Обработка почвы после применения препарата снижает гербицидную активность. При обработке посевов  после прорастания сорняков Оксифен 240 к. э. уничтожает сорняки, действуя как контактный гербицид и одновременно, как  почвенный гербицид, попадая на поверхность почвы. Отличается относительно высокой персистентностью (стойкостью) во  всех типах почвы за счет интенсивного поглощения и связывания его почвенными частицами. По этой причине препарат не  выщелачивается и не мигрирует из зон внесения, что обеспечивает длительный защитный эффект против сорняков.', 0, 128, 0, '', 1, ' Оксифлуорфен, 240 г/л.', ' Концентрат эмульсии.', 0),
(9, 'rimus-25', 'Римус 25%', 1, 2, 'Послевсходовый гербицид для борьбы со всеми злаковыми сорняками и большинством двудольных сорняков. Гербицид используют для уничтожения злаковой и двудольной многолетней  и однолетней сорной растительности в посадках кукурузы, посевного картофеля. Эффективен против всех злаковых, включая  пырей и гумай, а также против большинства двудольных сорняков на посевах кукурузы. Препарат используют в ранний период  развития картофеля и кукурузы (1-4 или 2-6 листьев у культуры  соответственно) по молодым сорнякам (высота пырея и других  сорных злаковых трав не должна превышать 15 см; осот полевой  в фазе образования розетки). Все культуры можно обрабатывать  как однократно, так и двукратно (через 10-20 дней).  На кукурузе – Опрыскивание посевов в фазе 3-5 листьев куль туры (в период начала кущения однолетних злаковых и высоте  многолетних сорняков 15-20 см). На картофеле – Опрыскивание  посадок после окучивания, при высоте культуры 5-20 см в ранние фазы развития (1-4 листа) однолетних сорняков, при высоте  пырея 10-15 см, осота в фазу розетки', 0, 129, 0, '', 1, ' Римсульфурон, 250 г/кг.', 'Водно-диспергируемые гранулы', 0),
(10, 'risulam', 'Рисулам', 1, 2, 'Послевсходовый селективный гербицид системного действия  для борьбы со злаковыми, двудольными и болотными сорняками (в т. ч куриное просо, виды клубнекамыша) в посевах  риса. Препарат проникает в растения через листовую поверхность и частично через корневую систему. Действующее  вещество гербицида Рисулам 250, к. с. ингибирует фермент  ацетолактатсинтазу (АЛС) у чувствительных видов сорняков.  Это приводит к остановке роста в течение нескольких часов  после обработки. Визуальные симптомы действия препарата  на сорняки (хлороз, увядание, бурая окраска) проявляются  обычно через 3–7 дней, а полная гибель сорняков наступает  через 2–4 недели. Оптимальный срок применения начало ку щения риса (4-6 листьев), фаза 2-5 листьев у клубнекамыша', 0, 130, 0, '', 1, ' Квинклорак, 250 г/л.', ' Концентрат суспензии', 0),
(11, 'ristoks', 'Ристокс', 1, 2, ' Послевсходовый гербицид системного действия для борьбы с  однолетними злаковыми (просовидные), осоковыми (клубнека мыш), и болотными сорняками в посевах риса.  Опрыскивание посевов в фазе от 1 листа – конец кущения культуры и ранние фазы роста сорняков (2-4 листа у злаковых и 5-7  листьев у осоковых, 6-7 листьев клубне-камыша, 2-4 листьев до  середины кущения куриного просо). Перед опрыскиванием рекомендуется полностью отвести воду из чеков. Повторное затопление можно проводить не ранее 3-х дней после обработки.  Запрещается технологический сброс воды из чека с момента  обработки пестицидом до конца восковой спелости риса (начало сентября). Расход рабочей жидкости 200-300 л/га при на земном опрыскивании и 50-100 л/га при авиационном', 0, 131, 0, '', 1, ' Пеноксулам + цигалафоп-бутил, 30 г/л + 150 г/л.', ' Масляная дисперсия МД.', 0),
(12, 'zlakosuper-7.5', 'Злакосупер 7.5%', 1, 2, ' Системный послевсходовый гербицид против однолетних злаковых сорняков на пшенице яровой и озимой.  Опрыскивание посевов ярового ячменя и яровой пшеницы  начинают по вегетирующим сорнякам в фазе от 2-го листа до  начала кущения, независимо от фазы развития основной культуры. Опрыскивание посевов озимой пшеницы начинают рано  весной по вегетирующим сорнякам. Первые признаки воздействия препарата проявляются в течение 24-48 часов. Полная  гибель сорных злаков наблюдается в течение 10-15 дней после  обработки. Препарат эффективно применяется по вегетирующим, злаковым сорнякам опрыскиванием в ранние фазы их  развития (2-3 листа) не зависимо от фазы развития культуры.', 0, 132, 0, '', 1, ' Феноксапроп-П-этил 69 г/л + мефенпирдиэтил (антидот), 75 г/л).', 'Эмульсия масляно водная.', 0),
(13, 'zlakoforte-100', 'Злакофорте 100', 1, 2, ' Системный послевсходовый гербицид против однолетних злаковых сорняков на пшенице яровой и озимой. Опрыскивание  посевов ярового ячменя и яровой пшеницы начинают по вегетирующим сорнякам в фазе от 2-го листа до начала кущения,  независимо от фазы развития основной культуры. Опрыскивание посевов озимой пшеницы начинают рано весной по вегетирующим сорнякам. Первые признаки воздействия препарата  проявляются в течение 24-48 часов.  Полная гибель сорных злаков наблюдается в течение 10-15 дней  после обработки. Препарат эффективно применяется по вегетирующим, злаковым сорнякам опрыскиванием в ранние фазы их  развития (2-3листа) независимо от фазы развития культуры.', 0, 133, 0, '', 1, 'Феноксапроп-П-этил, 100 г/л +  клоквинтоцет-мексил (антидот), 27 г/л.', ' Концентрат эмульсии', 0),
(14, 'zlako-pick', 'Злако Пик', 1, 2, 'Эффективный гербицид для защиты зерновых культур от особо злостных сорных растений. Опрыскивание посевов яровой пшеницы начинают по вегетирующим сорнякам в фазе от  3-го листа с добавлением прилипателя.', 0, 134, 0, '', 1, 'Клодинафоп-пропаргил 240 г/+  клоквинтоцет-мексил 60 г/л).', ' Концентрат эмульсии.', 0),
(15, 'tribuzin-700', 'Трибузин 700', 1, 2, ' Селективный системный гербицид, имеет широкий спектр  воздействия на однолетние двудольные и отдельные злаковые  сорняки до и послевсходовом периоде их развития на картофеле, томатах и на сое. Препарат применяется один раз в  течение сезона путем сплошного опрыскивания почвы. Картофель рекомендуется обрабатывать до появления всходов  культуры, томаты из семян опрыскиваются в стадии 2-4 листков культуры, с нормой расхода 0,8 кг/га, на участках, отведенных под томаты рассадные, грунт опрыскивается до высаживания рассады за 15-20 дней, норма расхода 1,0-1.6 кг/га.', 0, 135, 0, '', 1, ' Метрибузин, 700 г/кг.', 'Смачивающийся порошок.', 0),
(16, 'imazet-100', 'Имазет 100', 1, 2, 'Высокоэффективный системный гербицид для борьбы с широким спектром однолетних и многолетних злаковых и двудольных сорняков, в том числе видов повилик и амброзии на  бобовых культурах. Наиболее эффективный способ применения  гербицида на посевах сои – это ранее послевсходовое внесение. В этот период двудольные сорняки не должны иметь  более 4-х, а злаковые – более 2-3-х листьев. Обработку можно проводить до фазы 3-го тройчатого листа сои включительно. При обработке всходов, гербицид уже в течение одного  часа проникает в сорные растения и гарантирует их гибель,  что имеет большое значение в дождливую погоду.', 0, 136, 0, '', 1, ' Имазетапир, 100 г/л.', 'Водный концентрат.', 0),
(17, 'kalkan', 'Калкан', 1, 2, 'Системный довсходовый, гербицид избирательного действия,  предназначенный для борьбы с широким спектром однолетних  двудольных и злаковых сорняков в посевах сои, кукурузы, подсолнечника и лука. Действующее вещество поглощается корнями и побегами сорных растений. Сорняки, которые подверглись  действию препарата, вскоре после прорастания погибают. Эффект препарата проявляется по вегетирующим сорнякам. Пендиметалин, как и другие динитроанилины, ингибирует корневую  меристему, нарушает поздние стадии митоза. Он блокирует  образование белка – тубулина, из которого состоят микротрубочки, необходимые для деления клетки. Благодаря этому, обработка препаратом приводит к нарушению корневого питания,  замедлению развития и роста боковых корней, истощению и,  затем, гибели растений. Пендиметалин, как и другие динитроанилины, активен только по отношению к прорастающим семенам, поэтому предназначается лишь для почвенного внесения.', 0, 137, 0, '', 1, ' Пендиметалин, 330 г/л.', 'Концентрат эмульсии.', 0),
(18, 'pendimeks', 'Пендимэкс', 1, 2, 'Селективный системный довсходовый гербицид длительного  защитного действия для борьбы с однолетними злаковыми  и двудольными сорняками в посевах подсолнечника, лука и  моркови.', 0, 138, 0, '', 1, ' Пендиметалин, 400 г/л.', 'Концентрат эмульсии.', 0),
(19, 'geksil-extra', 'Гексил Экстра', 1, 2, ' Системный гербицид избирательного действия, предназначенный для борьбы с широким спектром однолетних двудольных сорняков в посевах зерновых колосовых культур и кукурузы.  Применение Гексил Экстра, в. р. в посевах зерновых колосовых  культур наиболее эффективно в фазе кущения культуры. Норма  расхода Гексил Экстра, в. р. составляет 1,0-1,5 л/га.  Для получения стабильного и высокодисперстного раствора  необходимо на половину заполнить бак опрыскивателя водой,  добавить необходимое количество Гексил Экстра, в.р., перемешать в течение 10-15 секунд, затем медленно наполнить бак водой. Гексил Экстра, в.р. используют однократно в течение одного вегетационного периода в фазу кущения зерновых до выхода  в трубку. Первые признаки эффективности наблюдаются через  12-18 часов. Расход рабочей жидкости 200-300 л/га.', 0, 139, 0, '', 1, ' 2,4 Д диметиламинная соль, 720 г/л.', 'Водный раствор.', 0),
(20, 'fluron', 'Флурон', 1, 2, ' Высокоэффективный послевсходовый системный гербицид для  борьбы с широким спектром двудольных однолетних и многолетних сорняков в том числе устойчивых к 2/4 Д в посевах  сахарной свеклы. Флурон, ВДГ обладает выраженным системным действием. Действующее вещество поглощается, главным  образом, листьями сорняков, и частично стеблями и корневой  системой. Препарат также обладает и некоторой почвенной  активностью, так, при наличии влаги в почве, он способен в  течение 1-2 недель подавлять всходы сорняков. Полная гибель  сорных растений наступает через несколько недель после обработки. В месте действия трифлусульфурон-метил ингибирует  синтез аминокислот. Уже через 3-4 часа после обработки рост  чувствительных сорняков прекращается, а через 4-7 дней наблюдаются симптомы повреждения сорняков.', 0, 140, 0, '', 1, ' Трифлусульфурон-метил 500 г/кг.', 'Водно-диспергируемые гранулы.', 0),
(21, 'avangard', 'Авангард', 1, 2, ' Авангард - Высокоэффективный довсходовый селективный гербицид против однолетних злаковых и некоторых двудольных сорняков в посевах сахарной свеклы, кукурузы, подсолнечника, сои.', 0, 141, 0, '', 1, ' С-метолахлор 960 г/л.', 'Концентрат эмульсии.', 0),
(22, 'avatar-35', 'Аватар, 35%', 1, 2, 'Аватар - Эффективное средство для защиты культур на начальной фазы роста растений. Эффективный контроль сорняков и бурьянов, действует на прорастающие сорняки. Исключает необходимость в проведении обработок гербицидом в  междурядьях.', 0, 142, 0, '', 1, 'Фомесафен, 95 г/л + хизалофоп-п-этил,  25 г/л + кломазон, 230 г/л,', 'Концентрат эмульсии.', 0),
(23, 'tsaritsa', 'Царица', 1, 1, 'Системный фунгицид для обработки зерновых колосовых культур  в период вегетации против видов ржавчин, септориоза, мучнистой  росы, септориозногельминтоспориозных пятнистостей и пирикуляриоза на рисе. Оказывает лечебный эффект при уже начавшемся  поражении. Быстро проникает и распространяется внутри растения, устойчив к воздействию осадков.  Царица, э. м. в. относится к демитилирующим ингибиторам (DMI  фунгициды), действие которых основано на процессе ингибирования биосинтеза стерина, а именно С-4-демитилазы в синтезе стерина патогенными организмами. После проникновения препарата,  производство эргостерина прекращается, происходит накоплении  промежуточных продуктов синтеза, что приводит к нестандартной  мембранной структуре, изменению свойств мембраны (например,  ее проницаемости), аномальному росту патогена, снижению воспроизводства и в конечном итоге – отмиранию клетки.', 0, 143, 0, '', 1, ' Тебуконазол, 250 г/л.', 'Эмульсия масляно водная.', 0),
(24, 'sila-plyus', 'Сила Плюс', 1, 1, ' Системный фунгицид для предпосевной обработки семян обладает защитным и лечебным действием. Применяется в борьбе  с различными видами головни, септориоза, снежной плесени,  гельминтоспориозной и фузариозной корневых гнилей, плесневения семян на яровой и озимой пшенице, яровом ячмене.  Протравливание семян суспензией препарата (10 л воды на  1 т семян). Рабочий раствор готовить непосредственно перед  применением и использовать в день приготовления. Расход  рабочей жидкости 10 л/тонну семян.', 0, 144, 0, '', 1, ' Тебуконазол, 120 г/л.', 'Концентрат суспензии.', 0),
(25, 'zebra-400', 'Зебра 400', 1, 1, ' Системный фунгицид широкого спектра действия. Обладает  защитными, лечебными и искореняющими свойствами. Фунгицид для обработки зерновых колосовых в борьбе с самыми  вредоносными заболеваниями листьев, стебля и колоса - видов ржавчин, септориоза, мучнистой росы, фузариозов, септориозногельминтспориозных пятнистостей, а также альтернариоза и фомоза рапса и церкоспороза, мучнистой росы,  фомоза и оидиума винограда. Оказывает лечебный эффект при  уже начавшемся поражении. Быстро проникает и распространяется внутри растения, устойчив к воздействию осадков.', 0, 145, 0, '', 1, ' Пропиконазол 200 г/л + тебуконазол 200 г/л.', 'Концентрат эмульсии.', 0),
(26, 'dikor', 'Дикор', 1, 1, 'Дикор к. э. (дифеноконазол, 250 г/л) контактный и системный  фунгицид, предназначенный для профилактики и лечения ряда  заболеваний плодовых культур.  Приготовление рабочей жидкости осуществляется на стационарных пунктах или с помощью передвижных агрегатов (АПР,  «Темп» или АПЖ-12), позволяющих тщательно размешивать препарат с водой в специальных емкостях. Указанные агрегаты  позволяют приготовленную рабочую жидкость фильтровать и с  помощью насосов подавать в емкости опрыскивателей. Перед  началом работы опрыскивателя необходимо включить мешалку.', 0, 146, 0, '', 1, ' Дифеноконазол, 250 г/л.', 'Концентрат эмульсии.', 1),
(27, 'koseyt-770', 'Косейт 770', 1, 1, ' Фунгицид контактного действия для защиты растений от множества заболеваний. Неорганический медный состав выступает контактным действующим агентом в большом перечне  препаратов защиты растений, и оказывает профилактические  и лечебные действия против грибковых и бактериальных заболеваний. Приготовление рабочей жидкости осуществляется на  стационарных пунктах или с помощью передвижных агрегатов  (АПР, «Темп» или АПЖ-12), позволяющих тщательно размешивать препарат с водой в специальных емкостях.', 0, 147, 0, '', 1, ' Гидроксид меди, 770 г/кг.', 'Смачивающийся порошок.', 1),
(28, 'agromyl-gold', 'Агромил Голд', 1, 1, ' Фунгицид Агромил Голд, с. п. следует применять в строгом соответствии сданными рекомендациями. Препарат должен применяться  профилактически, т. е. до появления видимых симптомов развития  болезни на культурных растениях. После последней обработки  фунгицидом Агромил Голд, с. п. (не позднее, чем через 7 дней) следует проводить опрыскивание контактными фунгицидами.', 0, 148, 0, '', 1, ' Манкоцеб 640 г/кг + Металаксил 80 г/кг.', 'Смачивающийся порошок.', 1),
(29, 'atset-200', 'Ацет 200', 1, 3, ' Ацет 200 р. п. является инсектицидом контактного, кишечного и  системного действия, обладает овицидной активностью. Действующее вещество блокирует никотинзависимые рецепторы ацетил холина в нервной системе. Действующее вещество нарушает передачу нервного импульса через синапс, и насекомое погибает  от сильного нервного перевозбуждения, эффективный при борьбе  с представителями семейства чешуйчатокрылых – Lepidoptera,  полутвердокрылых – Hemiptera, трипсов Thysanoptera, твердокрылых – Coleoptera и равнокрылых – Homoptera. Ацетамиприд  обладает быстрым и продолжительным действием, результат виден уже через один час, а срок защитного действия до 21 дня.  Способен распространяться по растению. Благодаря особому  механизму действия у вредных объектов к нему не проявляется  устойчивости. Сохраняет высокую биологическую эффективность  при нормальных и повышенных температурах. Совместим с большинством фунгицидов и инсектицидов которые применяются в те  же сроки, за исключением алкалиновых смесей.', 0, 149, 0, '', 1, ' Ацетамиприд, 200 г/кг.', 'Растворимый порошок.', 0),
(30, 'tiametrin', 'Тиаметрин', 1, 3, 'Комбинированный инсектицид, обладающий контактной и системной активностью против широкого спектра вредителей на  всех жизненных стадиях – от личинки до имаго. Обладает высокой эффективностью против вредителей на широком спектре культур. В состав препарата входят два действующих вещества, относящиеся к 2 различным химическим классам. Они  полностью дополняют друг друга, обеспечивая максимальную  и продолжительную защиту от вредителей.  Превосходная защита растений как при проведении плановых  обработок, так и при обработках в критических ситуациях.', 0, 150, 0, '', 1, ' Тиаметоксам, 141 г/л + Лямбда-цигалотрин, 106 г/л.', 'Суспензионный концентрат.', 0),
(31, 'karat_super-100', 'Карат супер 100', 1, 3, 'Пиретроидный инсектицид, предназначен для защиты многих  других культур от комплекса листогрызущих и сосущих вредителей, включая клещей, применяется также для обработки незагруженных складских помещений и прискладской территории  против комплекса амбарных вредителей. Карат Супер 100, к. э.  обладает выраженным «нокдаун –эффектом». Гибель насекомых наступает спустя 30 минут после обработки и до 2-3 часов  после обработки (в зависимости от климатических условий,  вида и физиологического состояния вредителя).  Преимущества препарата: уничтожение важнейших грызущих  и сосущих вредителей на многих культурах тройное действие:  контактное, кишечное и остаточное очень быстрая гибель вредителей на любой стадии развития совместимость в баковых  смесях с большинством пестицидов.', 0, 151, 0, '', 1, ' Лямбда-цигалотрин, 100 г/л.', 'Концентрат эмульсии.', 0),
(32, 'tsezar', 'Цезарь', 1, 3, 'Системный инсектицид контактно-кишечного действия высокоэффективный малотоксичный против широкого спектра вредителей, против которых отсутствует устойчивость.  Химическое действие основано на подавлении передачи стимулирующих импульсов в нервной системе насекомого. Препарат  блокирует нейронный проводящий путь (nicotinergic), который  чаще встречается у насекомых, чем у теплокровных животных  (что обеспечивает его селективное химическое воздействие,  являющееся более токсичным для насекомых, чем для теплокровных животных). Это блокирование приводит к накоплению  ацетилхолина, важного нейромедиатора, вызывая паралич насекомого и, в конечном счете, гибель. Препарат эффективен при  контактном воздействии и при попадании через желудок.', 0, 152, 0, '', 1, ' Имидаклоприд, 200 г/л.', 'Водный концентрат.', 0),
(33, 'tsifos-550', 'Цифос 550', 1, 3, ' Кишечно-контактный инсекто-акарицид эффективен в борьбе  с хлопковой совкой, паутинным клещом, тлями, дынной мухой,  итальянским прусом, азиатской и мароккской саранчой на  посевах хлопчатника, бахчевых культур и на участках заселенных саранчовыми вредителями. Цифос 550, к. э. применяется в период вегетации, во время первого появления уязвимой  стадии вредителя на культуре в период массового отрождения  вредителей. Обработка препаратом обеспечивает продолжительное защитное действие не менее 14 дней.', 0, 153, 0, '', 1, ' Циперметрин, 50 г/л + Хлорпирифос, 500 г/л.', 'Концентрат эмульсии.', 0),
(34, 'barin', 'Барин', 1, 4, ' Селективный акарицид широкого спектра, контактного действия с трансламинарными (глубоко проникающими) и трансовариальными свойствами. Подавляет широкий спектр паутинных и листовых клещей. Эффективно подавляет личинок  двукрылых минеров, трипсов и медяниц.  Преимущества: подавляет широкий спектр паутинных и листовых клещей, эффективно подавляет личинок двукрылых минеров, трипсов и медяниц. В течение 2 часов после нанесения  на растение полностью проникает внутрь тканей, фитофаги,  питаясь паренхимой и соками растения, поглощают препарат  и погибают. Благодаря быстрому разложению препарата на  поверхности растения, неподвержены воздействию препарата  энтомо-и акарифаги (полезные насекомые и клещи). Эффективен против клещей, которые резистентны к другим акарицидам.', 0, 154, 0, '', 1, ' Абамектин, 36 г/л.', 'Концентрат эмульсии.', 0),
(35, 'agro-admiral', 'Агро Адмирал', 1, 3, ' Агро Адмирал, к. э. - инсектицид кишечного и контактного действия из группы аналогов ювенильного гормона. Препарат активно используется на плодовых насаждениях против яблонной  плодожорки, калифорнийской щитовки.  Особенности борьбы с калифорнийской щитовкой во многом  обусловлены биологией вредителя. Рекомендуемая норма расхода Агро Адмирал, к. э. в борьбе с калифорнийской щитовкой  составляет 1,0 л/га в зависимости от численности вредителя. Для  предотвращения поврежденности растений наиболее благоприятными являются два срока применения - в ранневесенний  (первый) и летний (второй). Весенняя обработка совпадает с на чалом перехода зимующих личинок первого возраста во второй,  что наблюдается на фазе развития растений «зеленый конус». ', 0, 155, 0, '', 1, ' Пирипроксифен, 100 г/л.', 'Концентрат эмульсии.', 0),
(36, 'agro-lider', 'Агро Лидер', 1, 3, 'Смешанный инсектицид для защиты кукурузы, технических,  овощных и плодовых культур от комплекса листогрызущих и  сосущих вредителей на хлопчатнике, кукурузе и луке, в том  числе клещей на яблоне и хлопчатнике.  Применяется в период вегетации, во время первого появления уязвимой стадии вредителя в соответствии с прогнозом.  Обработка препаратом обеспечивает продолжительное защитное действие не менее 14 дней. Не снижает эффективности обработки, если через 2-3 часа после нее прошел дождь.  Для достижения высокого эффекта перед приготовлением  рабочего раствора рекомендуемая норма препарата на  гектар, разбавляется в небольшом количестве воды до получения однородной консистенции.', 0, 156, 0, '', 1, ' Эмамектин бензоат 50 г/кг + Тиаметоксам, 150 г/кг.', 'Водно-диспергируемые гранулы.', 1),
(37, 'korol-premium', 'Король Премиум', 1, 3, ' Эффективный инсектицид премиум класса для защиты хлопчатника, томатов от комплекса вредителей и участков заселенных саранчовыми.  Рабочую жидкость готовят непосредственно перед опрыскиванием на специально оборудованных стационарных заправочных узлах или пунктах в резервуарах с механическими  мешалками. Территория заправочных пунктов должна быть  асфальтирована или бетонирована и иметь санитарно-защитную зону не менее 200 м, которую после окончания работ  обязательно обезвреживают.', 0, 157, 0, '', 1, ' Хлорантранилипрол, 250 г/л.', 'Концентрат суспензии.', 0),
(38, 'pykwat-5', 'Пикват 5%', 2, 6, 'Данный пестицид ускорение созревания\n коробочек хлопчатника.', 0, 158, 0, '', 1, ' Мепикватхлорид, 50 г/л.', 'Водный раствор.', 0),
(39, 'agron-gold', 'Агрон Голд', 2, 6, ' Дефолиация листьев хлопчатника перед сбором урожая.  Преимущества препарата: Препарат стимулирует образование отделительного слоя клеток. В результате листья опадают зелеными, а не сухими. На кустах не остается подсохших  листьев, что исключает загрязнение хлопка-сырца при сборе  урожая. Препятствует возобновлению роста листвы. Ускоряет  естественное созревание нераскрытых коробочек, поэтому  качество волокна не ухудшается. Проникает в листья растений  в течение 12 ч.', 0, 159, 0, '', 1, ' Тидиазурон, 360 г/л + диурон, 180 г/л.', 'Суспензионный концентрат.', 0),
(40, 'gumat-7b', 'Гумат +7В', 2, 5, ' Комплексное удобрение на основе природных гуминовых с микроэлементами. Препарат совместим с большинством гербицидов, фунгицидов и инсектицидов, можно использовать в баковых  смесях.- Применяется для подкормки всех видов культур, а также для  замачивания семян перед посадкой.- Массовая доля питательных веществ не менее  400 г/л, 37 г/л с микроэлементами.- Повышает урожайность сельскохозяйственных культур.- Повышает устойчивость растений к засухе и другим  неблагоприятным факторам.- Способствует интенсивному восстановлению  и образованию гумуса в почвах, перегноях и компостах.', 0, 160, 0, '', 1, '', 'Гомогенная суспензия.', 0),
(41, 'novosyl', 'Новосил', 2, 5, ' Это природный стимулятор иммунитета и роста растений с фунгицидной активностью (способностью защищать от грибков). \nДействующее вещество: Природная смесь тритерпеновых кислот \nиз хвои пихты сибирской. Препарат совместим с большинством \nгербицидов, фунгицидов и инсектицидов, можно использовать \nв баковых смесях. Предназначен для предпосевной обработки \nсемян и опрыскивания растений в период их активного роста. \nПрименяется для всех видов овощных, зерновых и технических \nкультур, плодово-ягодных деревьев и кустарников.\n Действие препарата основано на свойстве тритерпеновых кислот, содержащихся в хвое пихты сибирской, стимулировать иммунитет растений, что приводит к следующим результатам:- Снижается заболеваемость растений к грибным болезням в 2-4 раза.- Повышается их устойчивость к неблагоприятным факторам \nвнешней среды – заморозкам и засухе.- Ускоряется прорастание семян и повышается их всхожесть и\n активность начального роста.- Ускоряется созревание плодов на 3-6 дней.- Увеличивается урожайность на 2-4%.- Значительно уменьшаются потери при хранении урожая за счет \nулучшения легкости плодов.', 0, 161, 0, '', 1, '', 'Водная эмульсия.', 0),
(42, 'zargreen-natural', 'Zargreen Natural', 2, 5, 'Специальное антистрессовое удобрение из растительного сырья,  с высоким содержанием аминокислот 40%. Помогает растениям  преодолевать стрессовые ситуации, стимулирует метаболизм и  усвоение питательных веществ, что существенно повышает урожайность и качество продукции даже в неблагоприятных условиях.  Применяется на всех сельскохозяйственных культурах в критические периоды роста и развития. Вносится совместно с пестицидами и растворами минеральных удобрений. \r\n<b>Назначение:</b>\r\n- Стимулирует рост корневой системы;\r\n- Укрепляет иммунную систему растений;\r\n- Повышает урожайность;\r\n- Активизирует обменные процессы;\r\n- Усиливает стрессоустойчивость к заморозкам, низким/высоким  температурам, градобою, к химическому и осмотическому стрессу;\r\n- Повышает устойчивость растений к засухе и засоленности;\r\n- Улучшает усвоение элементов питания;\r\n- Активизирует собственные защитные функции растений;\r\n- Восстанавливает активный рост после природных стрессов;\r\n- Усиливает транспорт агрохимикатов в клетки растений;\r\n- Повышает качество продукции;\r\n- Увеличивает эффективность гербицидов и средств защиты  растений при совместном применении.', 0, 162, 0, '', 1, '', 'Жидкое удобрение.', 0),
(43, 'seaweed-boron', 'Seaweed Boron', 2, 5, ' Бор содержащее удобрение, совместим с обычными удобрениями и пестицидами, тем не менее, рекомендован предварительный  тест на совместимость. Для наилучшего эффекта, рекомендуется  применять утром или вечером. Необходимо повторное использование, в случае непрекращающего дождя на протяжении 8-ми  часов после опрыскивания. <b>Назначение: </b>\r\n- Повышает жизнеспособность пыльцы, улучшает завязывание  семян и плодов;\r\n- Предотвращает и быстро устраняет дефицит бора;\r\n- Защищает цветки и фрукты от осыпания;\r\n- Поддерживает синтез клеточных стенок;\r\n- Наличие в составе азота, способствует эффективному усвоению бора.  \r\n<b>Основные ингредиенты: </b> \r\n B2О3 (оксид бора) - 400 г/л. \r\n Органическое вещество - 200 г/л. \r\n Экстракт морских водорослей - 200 г/л.\r\n  N (азот) - 50 г/л.', 0, 163, 0, '', 1, '', 'Водная эмульсия.', 0),
(44, 'alga_phosphate-k', 'Alga Phosphate K', 2, 5, ' Фосфор и калий содержащее удобрение, совместим с обычными  удобрениями и пестицидами, тем не менее, рекомендован предварительный тест на совместимость. Для наилучшего эффекта, рекомендуется применять утром или вечером. Необходимо повторное  использование, в случае непрекращающего дождя в течение 8-ми  часов после опрыскивания.  \r\n<b>Назначение: </b>\r\n- Повышает устойчивость к заболеваниям;\r\n- Регулирует рост цветков, способствует окрашиванию плодов,  улучшает их качество и урожайность;\r\n- Повышает коэффициент использования питательных веществ,  способно активировать вторичные и микроэлементы;\r\n- Скорость поглощения выше чем у ортофосфата, способствующее быстрой подкормке фосфатом и калием. \r\n<b> Основные ингредиенты: </b>\r\n Полисахариды морских водорослей – 1%  \r\nР2О3 (оксид фосфора) – 30% \r\n К2О -20% (оксид калия) – 20% \r\n Хелат лимонной кислоты – 1%  pH-4-6', 0, 164, 0, '', 1, '', '', 0),
(45, 'seafun', 'Seafun', 2, 5, ' Комплексное удобрение, совместим с обычными удобрениями  и пестицидами, тем не менее, рекомендован предварительный  тест на совместимость. Для наилучшего эффекта, рекомендуется  применять утром или вечером. Необходимо повторное использование, в случае непрекращающего дождя в течение 8-ми часов  после опрыскивания. \r\n <b>Назначение: </b>\r\n- Разработан с целью поддержки уровня множества микроэлементов;\r\n- ЭДТА и морские водоросли оказывают двойное хелатирующее  действие для быстрого усвоения питательных веществ;\r\n- Улучшает вкус и цвет фруктов;\r\n- Органическое вещество улучшает деятельность микроорганизмов.  \r\n<b>Основные ингредиенты: </b>\r\n Альгиновая кислота - 14 г/л.\r\n  Органическое вещество - 150г/л.\r\n  N (азот) - 90 г/л. \r\n P2O5 (оксид фосфора) - 30 г/л.\r\n  K2O (оксид калия) - 60 г/л. \r\n ЭДТА – железо 16 г/л. \r\n ЭДТА – медь 8 г/л.  \r\nЭДТА- цинк 12 г/л. \r\n ЭДТА – магний 4 г/л. \r\n рH - 7-9.', 0, 165, 0, '', 1, '', '', 0),
(46, 'seawinner-818', 'Seawinner 818', 2, 5, 'Чистый порошок создан на основе экстракта морских водорослей  с добавлением специально разработанного комплекса витаминов,  макро и микроэлементов, помогающего растению прорастать и  развить мощную корневую систему.\r\n<b>Назначение:</b>\r\n- Ускоряет и активизирует процессы корнеобразования;\r\n- Повышает всхожесть семян и энергию прорастания;\r\n- Способствует развитию вегетативной системы растений;\r\n- Способствует интенсивному росту сельскохозяйственных культур;\r\n- Повышает устойчивость к стрессу и болезням.  \r\n<b>Основные ингредиенты:</b> \r\nАльгиновая кислота 30%  \r\nКальций 0,2% \r\nАминокислоты 4% \r\n Магний 0,5% \r\n Органические вещества 40% \r\n Бор 0,5% \r\n ГРР 5000 промилле \r\n Цинк 0,5% \r\n Азот 1% \r\n Железо 0,6% \r\n Оксид калия 20', 0, 166, 0, '', 1, '', '', 0),
(47, 'cocoly', 'Cocoly', 2, 5, 'Органо-минеральное удобрение нового поколения для восстановления и поддержания естественного плодородия почвы с полезными бактериями и уникальным веществом PAS (полимерно –кислотное вещество- синтезированное из улиток) регулирующий РН  почвы и водных растворов. Содержит природный стимулятор роста.  Повышает урожайность и стойкость к неблагоприятным условиям,  способствует развитию мощной корневой системы и росту зеленой массы, увеличивает вкусовые качества и сохранность урожая,  обеспечивает быстрое и полноценное питание при внекорневом  (листовом),капельномвнесении и внесении в почву. Переводит недоступные формы элементов питания в доступные для растений, повышает устойчивость растений к дефициту влаги и засолению почвы.', 0, 167, 0, '', 1, '', '', 0);
