(15, 6, 'Свёкла сахарная\n', '', '1,0', '', '', 'Однолетние\nдвудольные сорняки (включая виды щирицы и некоторые злаковые сорняки (куриное просо, щетинники, метлица полевая).', 'Опрыскивание посевов в стадии семядолей у сорняков (по 1-й, 2-й и 3-й волне). Расход рабочей жидкости 300-350 л/га.\n', '', '-3'),
(16, 6, 'Свёкла сахарная\r\n', '', '1,5', '', '', 'Однолетние\r\nдвудольные сорняки (включая виды щирицы и некоторые злаковые сорняки (куриное просо, щетинники, метлица полевая).', 'Опрыскивание посевов в стадии 2-4 листьев у сорняков (по 1-й и 2-й волне). Расход рабочей жидкости 300-350 л/га.\r\n', '', '-2'),
(17, 6, 'Свёкла сахарная\r\n', '', '3,0', '', '', 'Однолетние\r\nдвудольные сорняки (включая виды щирицы и некоторые злаковые сорняки (куриное просо, щетинники, метлица полевая).', 'Опрыскивание посевов в фазе 4 настоящих листьев. культуры и ранние фазы роста сорняков. Расход рабочей жидкости 300-350 л/га\r\n\r\n', '', '-1'),
(18, 7, 'Свекла\nсахарная,\nхлопчатник, лен', '', '0,5\n', '', '', 'Однолетние злаковые\n', 'Опрыскивание вегетирующих Сорняков в период их активного роста (фаза 2-6 листьев). Расход рабочей жидкости 250-300 л/га.', '', '-1'),
(19, 7, 'Свекла\r\nсахарная', '', '1,0\r\n', '', '', 'Пырей ползучий, гумай и другие\r\nмноголетние злаковые', 'Опрыскивание вегетирующей культуры при высоте сорняков 10-15 см. Расход рабочей жидкости 250-300 л/га.\r\n', '', '-1'),
(20, 7, 'Хлопчатник', '', '1,0-1,5\r\n\r\n', '', '', 'Многолетние злаковые\r\n(гумай, свинорой, пырей ползучий)', 'Опрыскивание вегетирующей культуры при высоте сорняков 10-15 см. Расход рабочей жидкости 250-300 л/га.\r\n', '', '-1'),
(21, 7, 'Лен', '', '1,0-1,5\r\n\r\n', '', '', 'Пырей ползучий\r\n', 'Опрыскивание посевов при высоте льна 3-10 см и пырея 10-20 см.\r\n', '', '-1'),
(22, 7, 'Подсолнечник, сафлор, соя, картофель\r\n', '', '0,5-1,0\r\n\r\n\r\n', '', '', 'Однолетние\r\nи многолетние\r\nзлаковые сорняки\r\n', 'Опрыскивание вегетирующих Сорняков в период их активного роста . Расход рабочей жидкости 250-300 л/га.\r\n', '', '-1'),
(23, 7, 'Рапс\r\n', '', '0,5-1,0\r\n\r\n\r\n', '', '', 'Однолетние\r\nи многолетние\r\nзлаковые сорняки\r\n', 'Опрыскивание вегетирующих Сорняков в период их активного роста . Расход рабочей жидкости 250-300 л/га.\r\n', '', '-1'),
(24, 7, 'Лук\r\n', '', '1,0-1,5\r\n\r\n\r\n\r\n', '', '', 'Однолетние, много-\r\nлетние злаковые\r\nсорняки (пырей ползучий, гумай)', 'Опрыскивание вегетирующих Сорняков в период их активного роста . Расход рабочей жидкости 250-300 л/га.\r\n', '', '-1'),
(25, 8, 'Подсолнечник', '', '1,0', '', '', 'Однолетние двудольные сорняки\n', 'Опрыскивание почвы до всходов культуры. Расход рабочей жидкости 250-300 л/га\n', '', '-1'),
(26, 8, 'Лук (всех генераций)\r\n', '', '0,5\r\n', '', '', 'Однолетние двудольные сорняки\r\n', 'Опрыскивание посевов в фазе 2 листьев культуры. Расход рабочей жидкости 250-300 л/га\r\n', '', '-1'),
(27, 8, 'Лук (всех генераций)\r\n', '', '1,0\r\n', '', '', 'Однолетние двудольные сорняки\r\n', 'Повторное опрыскивание посевов в фазе 3 листьев культуры. Расход рабочей жидкости 250-300 л/га\r\n', '', '-1'),
(28, 8, 'Яблоня (сильно\r\nи среднерослые подвои)\r\n', '', '4,2-8,4\r\n', '', '', 'Однолетние двудольные сорняки\r\n', 'Опрыскивание весной вегетирующих сорняков высотой 10-15 см при условии защиты культуры. Расход рабочей жидкости 500 л/га\r\n', '', '-1'),
(29, 8, 'Сафлор\r\n', '', '1,0\r\n', '', '', 'Однолетние двудольные сорняки\r\n', 'Опрыскивание почвы до всходов культуры. Расход рабочей жидкости 250-300 л/га\r\n', '', '-1'),
(30, 9, 'Кукуруза (на зерно)', '', '70-80 г/га + ПАВ Тренд 90, 200 мл/га', '', '', 'Однолетние, многолетние злаковые и некоторые двудольные\nсорняки', 'Опрыскивание посевов в фазе 2-6 листьев культуры (в период начала кущения однолетних злаковых) при высоте злаковых сорняков 10-15 см и в фазе розетки осотов. Расход рабочей жидкости - 200-300 л/га\n', '', '60 (1)'),
(31, 9, 'Картофель', '', '80 г/га + ПАВ Тренд 90, 200 мл/га\r\n', '', '', 'Многолетние (пырей), однолетние\r\nзлаковые и некоторые двудольные\r\nсорняки', 'Опрыскивание посадок после окучивания, при высоте культуры 5-20 см В ранние фазы развития (1-4 листа) однолетних сорняков, при высоте пырея 10-15 см. Расход рабочей жидкости - 200-300 л/га\r\n', '', '- (1)'),
(32, 10, 'Рис', '', '1,8-2,4', '', '', 'Однолетние\nзлаковые\n(просовидные)', 'Опрыскивание посевов\nв фазе 2-3 листьев - (2-4 листа у сорняков). Расход рабочей жидкости -200-300 л/га\n', '', '-(1)'),
(33, 11, 'Рис', '', '1,5-2,0\n', '', '', 'Однолетние злаковые (просовидные), осоковые (клубнекамыш), и болотные сорняки\n', 'Опрыскивание посевов. в фазе от 1 листа конец кущения культуры и ранние фазы роста сорняков (2-4 листа у злаковых и 5-7 листьев. у осоковых, 6-7 листьев клубнекамыша, 2-4\nлистьев до середины\nкущения куриного просо). Перед опрыскиванием рекомендуется полностью отвести воду из чеков. Повторное затопление можно проводить не ранее 3-х дней после обработки. Запрещается технологический сброс\nводы из чека с момента.\nобработки пестицидом. до конца восковой спелости риса (начало сентября). Расход рабочей жидкости 200-300 л/га при наземном опрыскивании и 50-100 л/га при авиационном\n', '', '- (1)'),
(34, 12, 'Пшеница Яровая, озимая', '', '0,8-1,2', '', '', 'Однолетние\nзлаковые сорняки (овсюг, виды щетинника, просо\nкуриное)', 'Опрыскивание посевов по вегетирующим сорнякам, начиная с фазы 2-го листа до конца кущения (не зависимо от фазы развития культуры). Расход рабочей жидкости 200-300 л/га', '', '- (1)'),
(35, 12, 'Ячмень яровой, озимый\r\n', '', '0,6-0,9', '', '', 'Однолетние\r\nзлаковые сорняки (овсюг, виды щетинника, просо\r\nкуриное)', 'Опрыскивание посевов по вегетирующим сорнякам, начиная с фазы 2-го листа до конца кущения (не зависимо от фазы развития культуры). Расход рабочей жидкости 200-300 л/га', '', '- (1)'),
(36, 13, 'Пшеница Яровая, озимая', '', '0,6-0,9', '', '', 'Однолетние\nзлаковые\n(овсюг, виды щетинника,\nпросо куриное', 'Опрыскивание\nпосевов по вегетирующим\nсорнякам, начиная с фазы 2-го листа до конца кущения (не зависимо от фазы развития культуры). Расход рабочей жидкости - 200-300л/га\n', '', '-(1)'),
(37, 14, 'Пшеница Яровая, озимая\n', '', '0,1-0,15      0,15', '', '', 'Овсюг, щетинник, куриное просо', 'Опрыскивание\nпосевов\nв ранние фазы роста сорняков (3-4 листа) с добавлением прилипателя 1 л/га\n', '', '-1'),
(38, 15, 'Томаты', '', '1,0', '', '', 'Однолетние двудольные\nи злаковые', 'Опрыскивание растений через 15-20 дней после высадки рассады в грунт. Расход рабочей жидкости - 250-300 л/га\n', '', '-1'),
(39, 15, 'Картофель', '', '0,7-1,4', '', '', 'Однолетние двудольные\r\nи злаковые', 'Опрыскивание почвы\r\nдо и после всходов культуры Расход рабочей жидкости - 250-300 л/га\r\n', '', '-2'),
(40, 15, 'Соя (в условиях орошения)', '', '0,6-0,8', '', '', 'Однолетние двудольные\r\nи злаковые', 'Опрыскивание почвы\r\nдо всходов культуры. Расход рабочей\r\nжидкости - 250-300 л/га\r\n\r\n', '', '-1'),
(41, 16, 'Соя', '', '1,0-1,2', '', '', 'Однолетние, многолетние злаковые и двудольные, в т. ч. виды амброзии', 'Опрыскивание почвы до посева (с заделкой), до всходов или опрыскивание посевов в фазе 2-3\nнастоящих листьев культуры. В год применения препарата рекомендуется высевать озимую пшеницу, на следующий год - кукурузу, яровые и озимые зерновые; через 2 года - все культуры. Расход рабочей жидкости - 250-300 л/га.', '', '-(1)'),
(42, 16, 'Люцерна', '', '1,0', '', '', 'Однолетние,\nмноголетние\nзлаковые\nи двудольные, в т. ч. виды\nповилики', 'Опрыскивание посевов через 7-10 дней после 1 укоса. Расход рабочей жидкости - 250-300 л/га.\r\n', '', '-(1)'),
